<?php require 'config/db.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$s=$pdo->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->execute([$_POST['name'],$_POST['email'],password_hash($_POST['password'],PASSWORD_DEFAULT)]);header('Location:login.php');exit;}catch(PDOException $e){$msg='Email already exists.';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register | DrinkShop</title><link rel="stylesheet" href="css/style.css"></head><body class="form-page"><div class="auth-shell"><aside class="auth-side"><div><div class="mark">🥤 DrinkShop</div><h2>Create your<br>DrinkShop account.</h2><p>Save time at checkout and enjoy a smoother online ordering experience.</p></div><div class="auth-points"><span>✓ Browse drink menu</span><span>✓ Customize sugar & ice</span><span>✓ Track your order</span></div></aside><section class="auth-main"><div class="form-card"><div class="form-head"><h1>Create account</h1><p class="form-subtitle">Fill in your information below.</p></div><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><form method="post"><div class="field"><label>Full name</label><input name="name" placeholder="Your full name" autocomplete="name" required></div><div class="field"><label>Email address</label><input type="email" name="email" placeholder="you@example.com" autocomplete="email" required></div><div class="field"><label>Password</label><input type="password" name="password" placeholder="At least 6 characters" minlength="6" autocomplete="new-password" required></div><button class="btn">Create account</button></form><p class="form-foot">Already registered? <a href="login.php">Sign in</a></p><p class="form-foot"><a href="index.php">← Back to shop</a></p></div></section></div></body></html>